const tabId = 730410078;
const resultsData = await browserjs(tabId, () => {
  // Find all product listings
  // On Best Buy search / PLP, product items usually have classes like .sku-item or are in an ol/ul
  const items = [];
  const productElements = document.querySelectorAll('li.sku-item, [class*="sku-item"], [data-testid="sku-card"]');

  // If not found by sku-item, look for list items containing product links
  const allCards = productElements.length > 0 ? Array.from(productElements) : 
    Array.from(document.querySelectorAll('ol > li, ul > li')).filter(li => li.querySelector('h3, h4') && li.querySelector('[class*="price"]'));

  for (const card of allCards) {
    const titleEl = card.querySelector('h3, h4, [class*="title"] a, a[class*="product"]');
    const title = titleEl?.textContent?.trim().replace(/\s+/g, ' ');
    const link = titleEl?.closest('a')?.href || card.querySelector('a')?.href;

    // Price
    const priceEl = card.querySelector('[data-testid="customer-price"], .priceView-customer-price, [class*="current-price"]');
    const price = priceEl?.textContent?.trim();

    // Original / Regular Price
    const regPriceEl = card.querySelector('.pricing-price__regular-price, [data-testid="regular-price"], [class*="was-price"]');
    const regPrice = regPriceEl?.textContent?.trim();

    // Savings
    const savingsEl = card.querySelector('.pricing-price__savings, [data-testid="savings-price"], [class*="saving"]');
    const savings = savingsEl?.textContent?.trim();

    // Rating
    const ratingEl = card.querySelector('.c-ratings-reviews, [data-testid="rating-stars"], [aria-label*="rating"], [aria-label*="stars"]');
    const rating = ratingEl?.getAttribute('aria-label') || ratingEl?.textContent?.trim();

    // Model / SKU
    const skuEl = card.querySelector('.sku-value, [data-testid="sku-value"]');
    const sku = skuEl?.textContent?.trim();

    if (title) {
      items.push({ title, price, regPrice, savings, rating, sku, link });
    }
  }

  // Active filter pills / breadcrumbs
  const appliedFilters = Array.from(document.querySelectorAll('[data-testid="filter-pill"], .pill, .filter-pill, [class*="applied-filter"], [class*="facet-tag"]'))
    .map(el => el.textContent.trim().replace(/\s+/g, ' '));

  return {
    h1: document.querySelector('h1')?.textContent?.trim(),
    h2: Array.from(document.querySelectorAll('h2')).map(h => h.textContent.trim()),
    appliedFilters,
    totalFound: items.length,
    items: items.slice(0, 15)
  };
});

