    return !['Featured products', 'Recently viewed'].includes(h.textContent.trim());
  });

  const products = [];
  for (const h3 of h3s) {
    // Find the enclosing section/div that contains price
    let container = h3.parentElement;
    for (let i = 0; i < 6 && container && container !== document.body; i++) {
      if (container.innerText.includes('$')) {
        break;
      }
      container = container.parentElement;
    }

    if (container && container.innerText.includes('$')) {
      products.push({
        title: h3.textContent.trim().replace(/\s+/g, ' '),
        details: container.innerText.replace(/\n+/g, ' | ')
      });
    }
  }

  return {
    h1: document.querySelector('h1')?.textContent?.trim(),
    totalProductsFound: products.length,
    products: products.slice(0, 10)
  };
});
