const tabId = 730410078;
const filterOptions = await browserjs(tabId, () => {
  // Find Current Deals options and Price options
  const allFacets = Array.from(document.querySelectorAll('fieldset, [data-testid*="facet"], .facet-group, .c-facet-group, div'));

  // Find Current Deals facet
  const dealsFacet = allFacets.find(f => f.querySelector('h2, legend, button, span')?.textContent?.includes('Current Deals'));
  // Find Price facet
  const priceFacet = allFacets.find(f => f.querySelector('h2, legend, button, span')?.textContent?.includes('Price') && !f.querySelector('h2, legend, button, span')?.textContent?.includes('Current Deals'));

  const getInputs = (el) => {
    if (!el) return [];
    return Array.from(el.querySelectorAll('label, input, a, button')).map(i => ({
      tag: i.tagName,
      type: i.getAttribute('type'),
      name: i.getAttribute('name'),
      id: i.id,
      text: i.textContent.trim().replace(/\s+/g, ' '),
      ariaLabel: i.getAttribute('aria-label')
    }));
  };

  return {
    dealsText: dealsFacet?.innerText.slice(0, 500),
    dealsInputs: getInputs(dealsFacet),
    priceText: priceFacet?.innerText.slice(0, 500),
    priceInputs: getInputs(priceFacet)
  };
});

console.log(JSON.stringify(filterOptions, null, 2));

