    tag: h.tagName,
    text: h.textContent.trim().replace(/\s+/g, ' ')
  }));

  return {
    url: window.location.href,
    h1,
    activeFilters,
    allHeadings: allHeadings.slice(0, 25),
    itemsCount: items.length,
    sampleItems: items.slice(0, 5)
  };
});
console.log(JSON.stringify(pageState, null, 2));

