const cardDetails = await browserjs(tabId, () => {
  // Let's find the card container for one of the products, e.g. JBL Go 4 or Ultimate Ears MINIROLL
  const h3 = Array.from(document.querySelectorAll('h3')).find(h => h.textContent.includes('MINIROLL'));
  if (!h3) return "No MINIROLL found";
  // Traverse up to find the product card container
  let el = h3;
  let card = null;
  while (el && el !== document.body) {
    if (el.className && (el.className.includes('item') || el.className.includes('card') || el.tagName === 'LI')) {
      card = el;
      break;
    }
    el = el.parentElement;
  }
  return {
    h3Text: h3.textContent,
    cardTag: card?.tagName,
    cardClass: card?.className,
    cardText: card?.innerText
  };
});
console.log(cardDetails);

