const tabId = 730410078;
const detailedProducts = await browserjs(tabId, () => {
  // Find each distinct product on the page
  const seen = new Set();
  const list = [];

  // Best Buy uses either ol/ul with class product-list or sku-item, or main sections
  const productLinks = Array.from(document.querySelectorAll('a[href*="/product/"]'))
    .filter(a => a.innerText.trim().length > 15 && !a.href.includes('#tabbed-customerreviews'));

  for (const a of productLinks) {
    const title = a.innerText.trim().replace(/\s+/g, ' ');
    if (seen.has(title)) continue;
    seen.add(title);

    // Find parent container that holds the price
    let el = a;
    let card = null;
    for (let i = 0; i < 8 && el && el !== document.body; i++) {
      if (el.innerText.includes('$') && el.innerText.length > title.length + 10) {
        card = el;
        break;
      }
      el = el.parentElement;
    }

    let price = null;
    let wasPrice = null;
    let savings = null;
    let rating = null;

    if (card) {
      // Find prices
      const text = card.innerText;
      // Match price patterns
      const priceMatches = text.match(/\$\d+(\.\d{2})?/g);
      if (priceMatches && priceMatches.length > 0) {
        price = priceMatches[0];
        if (priceMatches.length > 1) {
          wasPrice = priceMatches[1];
        }
      }

      const saveMatch = text.match(/Save \$[\d\.]+/i);
      if (saveMatch) savings = saveMatch[0];

      const ratingMatch = text.match(/Rating ([\d\.]+) out of 5/i);
      if (ratingMatch) rating = ratingMatch[1] + " / 5";
    }

    list.push({
      title,
      price,
      wasPrice,
      savings,
      rating,
      href: a.href
    });
  }

  return {
    totalDistinct: list.length,
    list
  };
});

console.log(`Found ${detailedProducts.totalDistinct} products`);
console.log(JSON.stringify(detailedProducts.list.slice(0, 10), null, 2));

